import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it, expect } from "vitest";
import { TS_REP_SIGNALS, type SignalLandmark } from "../lib/repSignal";
import { DEFAULT_MIN_REP_SECONDS } from "../lib/repSegmentation";

// Ground truth generated by scripts/pose/capture_rep_signal_golden.py from a REAL clip, through each
// movement's real Python detector. The shared segmentation fixture pins signal->windows; this pins
// landmarks->signal, and nothing else does.
//
// NOT `new URL("../../../tests/...", import.meta.url)` — Vite 6's asset plugin statically rewrites
// that form into an http://.../@fs/... URL, which readFileSync rejects. Resolve from the test
// file's own directory instead, so the path stays independent of where vitest was launched from.
// (Same reason and same shape as lib.repSegmentation.test.ts.)
const FIXTURE = resolve(
  dirname(fileURLToPath(import.meta.url)), "../../../tests/fixtures/rep_signal_golden.json"
);
const golden = JSON.parse(readFileSync(FIXTURE, "utf-8")) as {
  source: string;
  movements: Record<string, {
    rep_signal: string; polarity: string; rectify: boolean; rep_start: string; min_rep_seconds: number;
  }>;
  cases: { landmarks: SignalLandmark[] | null; signals: Record<string, number | null> }[];
};

// Python's numeric path is float32 end to end (geometry.py:28 landmarks_to_array, :49
// visible_point, :109 mean_finite), while JS numbers are float64. On this fixture the largest
// observed float32-vs-float64 drift for the squat knee angle is ~1.45e-5 degrees (frame 28) --
// consistent with float32 epsilon (1.19e-7) at angle magnitudes of ~100 degrees; the other
// movements' angles are the same magnitudes through the same helpers. A real port divergence (2-D
// instead of 3-D, a different visibility gate, min instead of mean, the historical NaN-z collapse)
// is degrees or a NaN/number mismatch, not a fraction of a thousandth of a degree, so this constant
// has ~4 orders of magnitude of headroom below any real bug while comfortably clearing dtype noise.
const FLOAT32_TOLERANCE_DEGREES = 1e-4;

describe("the golden file covers exactly the ported movements", () => {
  it("has a Python value for every TS_REP_SIGNALS entry, and no movement TS does not port", () => {
    // A movement added to TS_REP_SIGNALS without regenerating would otherwise pass vacuously.
    expect(Object.keys(golden.movements).sort()).toEqual(Object.keys(TS_REP_SIGNALS).sort());
  });

  it("every ported movement uses the default rep knobs, the only ones planReps passes", () => {
    // planReps/refineSegments call segmentReps with no polarity/rectify/repStart/minRepSeconds, and
    // valleyPosition anchors spans on an argmin. A movement whose Python detector says otherwise
    // would get windows the backend then trusts -- wrong ones. See TS_REP_SIGNALS.
    for (const [movement, knobs] of Object.entries(golden.movements)) {
      expect(
        { polarity: knobs.polarity, rectify: knobs.rectify, rep_start: knobs.rep_start,
          min_rep_seconds: knobs.min_rep_seconds },
        movement
      ).toEqual({ polarity: "min", rectify: false, rep_start: "extended",
        min_rep_seconds: DEFAULT_MIN_REP_SECONDS });
    }
  });
});

describe.each(Object.keys(TS_REP_SIGNALS))("%s rep signal matches Python on real landmarks", (movement) => {
  const signal = TS_REP_SIGNALS[movement];

  it("has measurable frames in the golden file", () => {
    expect(golden.cases.length).toBeGreaterThan(0);
    expect(golden.cases.some((c) => typeof c.signals[movement] === "number")).toBe(true);
  });

  it("agrees within float32-vs-float64 precision on every frame", () => {
    for (const [i, testCase] of golden.cases.entries()) {
      const expected = testCase.signals[movement];
      expect(expected, `frame ${i} has no ${movement} entry`).not.toBeUndefined();
      const got = signal(testCase.landmarks);
      if (expected === null) {
        expect(Number.isNaN(got), `frame ${i} should be unmeasurable`).toBe(true);
      } else {
        expect(Math.abs(got - expected), `frame ${i}`).toBeLessThan(FLOAT32_TOLERANCE_DEGREES);
      }
    }
  });
});
